// Telegram's Bot API sends { message: { text, chat: { id }, voice?: {...}, ... } }.
// Voice messages have no `.text` field -- pass null through rather than
// guessing at transcription here (see README: transcription isn't wired
// up in this build). /arc-status/extract already handles null/empty text
// gracefully, so this stays a plain reshape with no branching logic.
const msg = $input.first().json.message;
return [{
  json: {
    text: msg.text || null,
    chat_id: msg.chat.id
  }
}];
